-- ----------------------------------------------------------------------------
-- FILL IN WHAT A NORMAL SIGN-UP WOULD SET (runs after BOTH auth.users inserts)
-- ----------------------------------------------------------------------------
update auth.users
set instance_id = coalesce(instance_id, '00000000-0000-0000-0000-000000000000'),
    raw_app_meta_data = case when raw_app_meta_data is null or raw_app_meta_data = '{}'::jsonb
                             then '{"provider":"email","providers":["email"]}'::jsonb
                             else raw_app_meta_data end,
    raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb),
    created_at = coalesce(created_at, now()),
    updated_at = coalesce(updated_at, now()),
    confirmation_token = coalesce(confirmation_token, ''),
    recovery_token = coalesce(recovery_token, ''),
    email_change = coalesce(email_change, ''),
    email_change_token_new = coalesce(email_change_token_new, ''),
    email_change_token_current = coalesce(email_change_token_current, ''),
    phone_change = coalesce(phone_change, ''),
    phone_change_token = coalesce(phone_change_token, ''),
    reauthentication_token = coalesce(reauthentication_token, '');

-- The umpire accounts were given a placeholder hash that nothing can match.
-- Give every one of them the real password 'umpire111' so you can demo signing in as an umpire.
update auth.users
set encrypted_password = extensions.crypt('umpire111', extensions.gen_salt('bf'))
where email like '%@rwcll.test';

-- One "email" sign-in identity for every user that does not have one yet.
insert into auth.identities (id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
select gen_random_uuid(), u.id, u.id::text, 'email',
       jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
       now(), now(), now()
from auth.users u
where not exists (select 1 from auth.identities i where i.user_id = u.id);

