-- Adults agreed to text messages. The database only lets the ACCOUNT HOLDER turn
-- that on (so nobody can consent for someone else), so each of these is made
-- as if that person had chosen it themselves, by signing the request as them.
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES
      ('10000000-0000-0000-0000-000000000001', '650-555-0101'),
      ('10000000-0000-0000-0000-000000000002', '650-555-0102'),
      ('10000000-0000-0000-0000-000000000003', '650-555-0103'),
      ('10000000-0000-0000-0000-000000000004', '650-555-0104'),
      ('10000000-0000-0000-0000-000000000005', '650-555-0105'),
      ('10000000-0000-0000-0000-000000000006', '650-555-0106'),
      ('10000000-0000-0000-0000-000000000007', '650-555-0107'),
      ('10000000-0000-0000-0000-000000000008', '650-555-0108')
    ) AS v(profile_id, phone)
  LOOP
    PERFORM set_config('request.jwt.claim.sub', r.profile_id, true);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.profile_id, 'role', 'authenticated')::text, true);

    INSERT INTO public.account_contact (profile_id, phone, sms_opt_in)
    VALUES (r.profile_id::uuid, r.phone, true)
    ON CONFLICT (profile_id) DO UPDATE SET phone = EXCLUDED.phone, sms_opt_in = true;
  END LOOP;

  -- back to nobody signed in
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claims', '', true);
END
$$;

