-- let every @rwcll.test account sign in (the same steps as section 7, for the accounts added since)
UPDATE auth.users
SET instance_id = COALESCE(instance_id, '00000000-0000-0000-0000-000000000000'),
    raw_app_meta_data = CASE WHEN raw_app_meta_data IS NULL OR raw_app_meta_data = '{}'::jsonb THEN '{"provider":"email","providers":["email"]}'::jsonb ELSE raw_app_meta_data END,
    raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb),
    created_at = COALESCE(created_at, now()), updated_at = COALESCE(updated_at, now()),
    confirmation_token = COALESCE(confirmation_token, ''), recovery_token = COALESCE(recovery_token, ''),
    email_change = COALESCE(email_change, ''), email_change_token_new = COALESCE(email_change_token_new, ''),
    email_change_token_current = COALESCE(email_change_token_current, ''), phone_change = COALESCE(phone_change, ''),
    phone_change_token = COALESCE(phone_change_token, ''), reauthentication_token = COALESCE(reauthentication_token, '')
WHERE email LIKE '%@rwcll.test';

UPDATE auth.users SET encrypted_password = extensions.crypt('umpire111', extensions.gen_salt('bf')) WHERE email LIKE '%@rwcll.test';

INSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
SELECT gen_random_uuid(), u.id, u.id::text, 'email',
       jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
       now(), now(), now()
FROM auth.users u
WHERE NOT EXISTS (SELECT 1 FROM auth.identities i WHERE i.user_id = u.id);

