-- Lets the app's "Demo clock" control set a PRETEND time, so a Saturday game can
-- be tried on a Thursday. (Needs 20261101100000_add_demo_clock.sql applied.)
-- To turn it off again:
--   update public.app_settings set value = 'false' where key = 'demo_clock_allowed';
-- NEVER turn this on for the live database.
