update public.app_settings set value = 'true' where key = 'demo_clock_allowed';

-- ============================================================================
-- FINAL CHECK (read-only): every account should say OK.
-- Anything else tells you what is missing for that account.
-- ============================================================================
select * from (
  select u.email,
    case
      when u.instance_id is null then 'PROBLEM: no instance_id'
      when not exists (select 1 from auth.identities i where i.user_id = u.id) then 'PROBLEM: no sign-in identity'
      when u.encrypted_password <> extensions.crypt(
             case when u.email = 'erik@rwcll.org' then 'erikRWCLL111'
                  when u.email in ('dan@rwcll.org', 'stephentwashington0@gmail.com', 'scott@rwcll.org', 'christrester@gmail.com', 'sammons@rwcll.org') then 'rwcllTest4$4'
                  when u.email like '%@rwcll.test' then 'umpire111'
                  else split_part(u.email, '@', 1) || '111' end,
             u.encrypted_password) then 'PROBLEM: password does not match'
      when p.id is null then 'PROBLEM: no profile'
      when p.account_status <> 'approved' then 'PROBLEM: profile not approved'
      when coalesce(trim(p.display_name), '') = '' then 'PROBLEM: profile has no name'
      when not exists (select 1 from public.user_roles r where r.user_id = u.id) then 'PROBLEM: no role'
      else 'OK'
    end as status
  from auth.users u
  left join public.profiles p on p.id = u.id
) t
order by (status = 'OK'), email;
